# Builds a Markdown catalog of every template's @description and writes it
# into README.md, replacing whatever currently sits between two marker
# comments. Run this after adding or changing a @description entry so the
# README stays in sync without hand-editing a table.
#
# Usage:
#   Rscript generate_catalog.R <path-to-xml-templates-checkout>
#
# Looks for (and, on first run, appends) these markers in that checkout's
# README.md:
#   <!-- BEGIN TEMPLATE CATALOG (auto-generated by generate_catalog.R; do not edit by hand) -->
#   ...catalog...
#   <!-- END TEMPLATE CATALOG -->
#
# Intentionally has no dependency on the dowser package (same as
# make_all_templates_from_base.R and lint_templates.R) -- this repo should
# be lintable/buildable/documentable on its own. The block-locating and
# @description-extraction logic here is a deliberately small duplicate of
# .parseTemplateInfo() in dowser's R/TimeTreesFunctions.R; keep both in
# sync by hand if the dowser-template-info grammar ever changes.

BEGIN_MARKER <- "<!-- BEGIN TEMPLATE CATALOG (auto-generated by generate_catalog.R; do not edit by hand) -->"
END_MARKER   <- "<!-- END TEMPLATE CATALOG -->"

# Extracts just the @description entry (with continuation lines joined) from
# a template's raw lines. Returns NA if there's no dowser-template-info
# block, the block is malformed (unclosed), or the block has no
# @description entry.
.extract_description <- function(xml) {
  start_idx <- grep("^\\s*<!--\\s*dowser-template-info\\s*$", xml)
  if (length(start_idx) == 0) {
    return(NA_character_)
  }
  start_idx <- start_idx[1]

  end_idx <- grep("^\\s*-->\\s*$", xml)
  end_idx <- end_idx[end_idx > start_idx]
  if (length(end_idx) == 0) {
    return(NA_character_) # malformed block -- lint_templates.R is where this gets flagged
  }
  end_idx <- end_idx[1]

  if (end_idx == start_idx + 1) {
    return(NA_character_) # empty block
  }
  block <- xml[(start_idx + 1):(end_idx - 1)]

  description_pattern <- "^\\s*@description\\s*\\|\\s*(.*)$"
  var_pattern          <- "^\\s*@var\\s+\\S+\\s*\\|"
  struct_pattern       <- "^\\s*@struct\\s+\\S+\\s*\\|"

  description <- NA_character_
  in_description <- FALSE

  for (line in block) {
    if (grepl(description_pattern, line)) {
      m <- regmatches(line, regexec(description_pattern, line))[[1]]
      description <- trimws(m[2])
      in_description <- TRUE
    } else if (grepl(var_pattern, line) || grepl(struct_pattern, line)) {
      in_description <- FALSE
    } else if (in_description && !grepl("^\\s*$", line)) {
      description <- paste(description, trimws(line)) # continuation line
    }
  }

  description
}

# One row's worth of (relative path, description) for every .xml file
# under root, grouped by top-level folder in the order given. Dot-folders
# (.base, and anything else starting with "." -- .git, .github, etc.) are
# never cataloged: they aren't user-facing template folders someone would
# pick a file from, even though .base is where the @description text
# originates. This check is written generically, not just as "skip
# .base", in case this folder list ever becomes a dynamic directory scan
# (e.g. list.dirs()) rather than the hardcoded vector below.
.collect_catalog_rows <- function(root) {
  folders <- c("StrictClock", "UCLD", "TypeLinked",
               "simplified/StrictClock", "simplified/UCLD", "simplified/TypeLinked")

  rows <- list()
  for (folder in folders) {
    if (grepl("^\\.", basename(folder))) {
      next # skip dot-folders
    }
    dir_path <- file.path(root, folder)
    if (!dir.exists(dir_path)) {
      next
    }
    files <- sort(list.files(dir_path, pattern = "\\.xml$", full.names = FALSE))
    if (length(files) == 0) {
      next
    }
    for (f in files) {
      xml <- readLines(file.path(dir_path, f), warn = FALSE)
      desc <- .extract_description(xml)
      rows[[length(rows) + 1]] <- list(folder = folder, file = f, description = desc)
    }
  }
  rows
}

# Markdown lines for the catalog, one ### subsection per folder with a
# two-column table of filename / description. A file with no @description
# shows a visible placeholder rather than being silently omitted, so a gap
# in documentation shows up in the README itself, not just in lint output.
build_catalog <- function(root) {
  rows <- .collect_catalog_rows(root)
  if (length(rows) == 0) {
    return(c("_No templates found._"))
  }

  folders_present <- unique(vapply(rows, function(r) r$folder, character(1)))
  lines <- character(0)

  for (folder in folders_present) {
    lines <- c(lines, paste0("### `", folder, "/`"), "", "| File | Description |", "|---|---|")
    folder_rows <- Filter(function(r) r$folder == folder, rows)
    for (r in folder_rows) {
      desc <- if (is.na(r$description)) "_(no @description yet)_" else r$description
      lines <- c(lines, paste0("| `", r$file, "` | ", desc, " |"))
    }
    lines <- c(lines, "")
  }

  lines
}

# Base R's `:` operator counts DOWNWARD when the left side is bigger than
# the right (e.g. 5:3 -> c(5, 4, 3)), rather than returning an empty
# sequence as a "from:to" range normally would when from > to. This bites
# exactly at the edges of a vector -- e.g. (n+1):n should mean "nothing
# after the last element" but instead yields c(n+1, n), pulling in an
# out-of-bounds NA plus the last element again. Used anywhere a marker
# might be the very first or very last line (the catalog section, being
# appended last on bootstrap, routinely has its END marker as the last
# line of the file), so this helper replaces every from:to in this file.
.safe_seq <- function(from, to) {
  if (from > to) integer(0) else from:to
}

# Replaces everything between BEGIN_MARKER/END_MARKER in readme_path with
# catalog_lines. If the markers aren't present yet, appends a new section
# (with the markers) to the end of the file instead of erroring, so this
# can bootstrap itself on a README that's never had a catalog before.
update_readme <- function(readme_path, catalog_lines) {
  readme <- readLines(readme_path, warn = FALSE)

  begin_idx <- grep(BEGIN_MARKER, readme, fixed = TRUE)
  end_idx   <- grep(END_MARKER, readme, fixed = TRUE)

  new_block <- c(BEGIN_MARKER, "", catalog_lines, END_MARKER)

  if (length(begin_idx) == 1 && length(end_idx) == 1 && begin_idx < end_idx) {
    before <- readme[.safe_seq(1, begin_idx - 1)]
    after  <- readme[.safe_seq(end_idx + 1, length(readme))]
    readme <- c(before, new_block, after)
  } else {
    readme <- c(readme, "", "## Template catalog", "", new_block)
  }

  writeLines(readme, readme_path)
}

# ---- CLI ---------------------------------------------------------------
# Only runs under `Rscript generate_catalog.R <path>`, not when this file
# is source()'d for its functions elsewhere.
if (!interactive() && sys.nframe() == 0) {
  args <- commandArgs(trailingOnly = TRUE)
  if (length(args) < 1) {
    stop("Please provide the path to an xml-templates checkout.")
  }

  root <- args[1]
  catalog_lines <- build_catalog(root)
  update_readme(file.path(root, "README.md"), catalog_lines)
  cat("Updated", file.path(root, "README.md"), "\n")
}
